def run(pts):
    out = []
    for k in range(len(pts)-1):
        x0, y0 = pts[k]; x1, y1 = pts[k+1]
        dx = (x1 > x0) - (x1 < x0); dy = (y1 > y0) - (y1 < y0)
        x, y = x0, y0
        while (x, y) != (x1, y1):
            out.append((x, y, dx, dy)); x += dx; y += dy
    out.append((pts[-1][0], pts[-1][1], dx, dy))
    return out
def bdir(dx, dy):
    if dx == 1: return 'R'
    if dx == -1: return 'L'
    if dy == 1: return 'D'
    return 'U'
def belt(pts):
    for (x, y, dx, dy) in run(pts):
        pl(Prototype.TransportBelt, x, y, bdir(dx, dy))
